def count_hexagons_summation(N):
    """Calculates H(N) = sum_{k=0}^{N-1} (3k^2 - 3k + 1)"""
    if N <= 0:
        return 0
    total = 0
    for k in range(N):
        term = 3 * k**2 - 3 * k + 1
        total += term
    return total

def count_hexagons_closed_form(N):
    """Calculates H(N) = N(N^2 - 3N + 3)"""
    if N < 1:
        return 0
    return N * (N**2 - 3*N + 3)

N_values = [1, 2, 3, 4]
results = {}

for N in N_values:
    sum_result = count_hexagons_summation(N)
    cf_result = count_hexagons_closed_form(N)
    results[N] = {
        "Summation": sum_result,
        "Closed Form": cf_result
    }

for N, res in results.items():
    print(f"N={N}: Summation={res['Summation']}, Closed Form={res['Closed Form']}")
